void anti_debug_fork_ptrace() {
    pid_t child = fork();

    if (child == 0) {
        // Child process traces parent
        if (ptrace(PTRACE_ATTACH, getppid(), NULL, NULL) == 0) {
            // Successfully attached to parent
            ptrace(PTRACE_CONT, getppid(), NULL, NULL);

            // Parent is now being traced by us
            // If another debugger tries to attach, it will fail

            // Child can monitor parent or just exit
            _exit(0);
        }
    } else if (child > 0) {
        waitpid(child, NULL, 0);  // Wait for child to setup
    }
    // If fork fails or ptrace fails, continue anyway
}
