void anti_debug_timing() {
    struct timespec start, end;

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Do some meaningless but time-consuming work
    volatile int i;
    for (i = 0; i < 1000000; i++);

    clock_gettime(CLOCK_MONOTONIC, &end);

    long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000 + 
                      (end.tv_nsec - start.tv_nsec);

    // If execution is too slow (likely being single-stepped in debugger)
    // Typical threshold: > 50ms in debugger vs < 5ms normal
